pa_scripts.script:
function caseService() {
	var s = current['business_service'];
	if (!gs.nil(s)) return s.toString();
	var o = current['service_offering'];
	if (gs.nil(o)) return null;
	var g = new GlideRecord('service_offering');
	if (g.get(o)) return g.getValue('parent');
	return null;
}
var getHierarchy = function(seed, parentField, tableName) {
	var h = [];
	while (seed) {
		h.push(seed.toString());
		var g = new GlideRecord(tableName);
		if (g.get(seed)) { seed = g.getValue(parentField); } else { seed = null; }
		if (new ArrayUtil().contains(h, seed)) break;
		if (g.getValue(parentField) == g.getValue('sys_id')) break;
	}
	return h;
};
function caseTaxonomy() {
	var s = caseService();
	if (gs.nil(s)) return null;
	var g = new GlideRecord('cmdb_ci_service');
	if (!g.get(s)) return null;
	return getHierarchy(g.getValue('spm_taxonomy_node'), 'parent', 'spm_taxonomy_node');
}
caseTaxonomy();
